    """Render one markdown unit to clean spoken text. list_mode "current" reads a whole
    list (however many items) as one run-on sentence, same as every other unit. list_mode
    "items" splits it: each top-level and nested item becomes its own newline-separated
    line, in document order. apply_steps_2_4 toggles sanitize_spoken's marker-strip/
    whitespace steps off (keeping only its HTML-tag reduction) for the round-4 "are they
    still needed" experiment; production always leaves it True."""
    if _FENCE.match(unit):
        return "Code sample."

    if _TABLE_ROW.match(unit.lstrip().split("\n", 1)[0]):
        return _table_to_spoken(unit, apply_steps_2_4)

    if list_mode == "items" and _is_list(unit):
        return _list_to_spoken_items(unit, apply_steps_2_4)

    out: list[str] = []

    for tok in _md.parse(unit):
        if tok.type != "inline":
            continue

        for child in tok.children or []:
            if child.type in ("text", "code_inline"):
                out.append(child.content)
            elif child.type in ("softbreak", "hardbreak"):
                out.append(" ")

    return sanitize_spoken("".join(out), apply_steps_2_4)


def _is_list(unit: str) -> bool:
    for line in unit.split("\n"):
        stripped = line.strip()
        if stripped == "":
            continue
        return bool(_LIST_ITEM.match(line))
    return False


def _list_to_spoken_items(unit: str, apply_steps_2_4: bool = True) -> str:
    """Walk the parsed tree for one list unit and emit one line per list item, an item's
    own text flushed before its nested sub-list is walked (so the item that introduces a
    nested list reads before its children, not after — nested items simply follow as more
    lines in the same sequence, giving the nested list a newline on either side for free).
    Lines are newline-joined, never merged into a run-on: between items, around a nested
    list, and between a multi-paragraph item's own paragraphs alike. An ordered item's
    line is prefixed with its literal position ("1. ...", continuing from a non-1
    `start`); no full stop is added — the source had none to begin with."""
    tree = SyntaxTreeNode(_md.parse(unit))
    lines: list[str] = []

    def inline_text(node, parts: list[str]) -> None:
        for child in node.children:
            if child.type in ("text", "code_inline"):
                parts.append(child.content)
            elif child.type in ("softbreak", "hardbreak"):
                parts.append(" ")

    def own_text(item) -> str:
        pieces: list[str] = []

        def walk_children(node) -> None:
            if node.type in ("bullet_list", "ordered_list"):
                return
            if node.type == "inline":
                parts: list[str] = []
                inline_text(node, parts)
                pieces.append(sanitize_spoken("".join(parts), apply_steps_2_4))
                return
            for child in node.children:
                walk_children(child)

        for child in item.children:
            walk_children(child)
        return "\n".join(piece for piece in pieces if piece != "")

    def walk(list_node) -> None:
        ordered = list_node.type == "ordered_list"
        number = int(list_node.attrs.get("start", 1)) if ordered else 0
        for item in list_node.children:
            text = own_text(item)
            if text != "":
                lines.append(f"{number}. {text}" if ordered else text)
            if ordered:
                number += 1
            for child in item.children:
                if child.type in ("bullet_list", "ordered_list"):
                    walk(child)

    for top in tree.children:
        if top.type in ("bullet_list", "ordered_list"):
            walk(top)

    return "\n".join(lines)


def is_unspeakable(spoken: str) -> bool:
    return not any(c.isalnum() for c in spoken)


def sanitize_spoken(text: str, apply_steps_2_4: bool = True) -> str:
    # Step 1: tag-to-word reduction — always applied, even with steps 2-4 off.
    text = _SPOKEN_HTML_TAG.sub(r"\1", text)

    if not apply_steps_2_4:
        return text.strip()

    # Step 2: marker-to-space (now including GFM's `~~` strikethrough marker).
    text = re.sub(r"\*\*|__|\*|~~|`", " ", text)
    # Step 3: drop horizontal whitespace before punctuation.
    text = re.sub(r"[ \t]+([,.;:!?])", r"\1", text)
    # Step 4: collapse whitespace — horizontal runs only; a newline is a deliberate line
    # break (the list walker's own item/paragraph boundary) and is never merged into a
    # space, only de-duplicated when more than one appears in a row.
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"[ \t]*\n[ \t]*", "\n", text)
    text = re.sub(r"\n{2,}", "\n", text)

    return text.strip()


